// src/self-improvement/prompt-factory.ts
function clampScore(value) {
  if (!Number.isFinite(value)) return 0;
  return Math.max(0, Math.min(10, value));
}
function riskPenalty(risk) {
  if (risk === "high") return 4;
  if (risk === "medium") return 2;
  return 0;
}
function opportunityScore(opportunity) {
  return clampScore(opportunity.leverage) * 2 + clampScore(opportunity.urgency) - riskPenalty(opportunity.rollbackRisk) - (opportunity.blockedBy?.length ? 6 : 0);
}
function bulletLines(values) {
  if (!values.length) return "- none";
  return values.map((value) => `- ${value}`).join("\n");
}
var verificationReportTemplate = {
  passFailRule: "Report PASS only when every verification command has observed output and zero relevant failures.",
  evidenceFreshnessHours: 12,
  requiredSections: [
    "Commands run",
    "Observed pass/fail evidence",
    "Blocked or skipped checks",
    "Remaining rollback risk",
    "Next recommended prompt"
  ]
};
function buildPrompt(opportunity, previous, loopUpgrade) {
  const verificationFriction = [...previous.friction, ...opportunity.verificationFriction ?? []];
  return [
    `Goal: ${opportunity.goal}`,
    "",
    "Context:",
    `- Previous verified improvement: ${previous.title}`,
    `- Evidence carried forward: ${previous.evidence.join("; ") || "none"}`,
    "",
    "Likely files/surfaces:",
    bulletLines(opportunity.likelyFiles),
    "",
    "Safety guardrails:",
    bulletLines(opportunity.safetyGuardrails),
    "",
    "Verification commands:",
    bulletLines(opportunity.verificationCommands),
    "",
    "Verification friction to watch:",
    bulletLines(verificationFriction),
    "",
    "Expected evidence:",
    bulletLines(opportunity.expectedEvidence),
    "",
    `Rollback risk: ${opportunity.rollbackRisk}`,
    "",
    "Self-improvement-loop check:",
    `- Apply this loop upgrade while working: ${loopUpgrade}`,
    "- Do not start another prompt until this prompt has pass/fail evidence.",
    "- If verification is blocked, stop and report the blocker instead of stacking more prompts."
  ].join("\n");
}
function chooseLoopUpgrade(previous) {
  if (previous.friction.some((item) => /test|verify|evidence/i.test(item))) {
    return "Put exact verification command and observed output in the next prompt before any implementation notes.";
  }
  if (previous.friction.some((item) => /scope|large|broad|unclear/i.test(item))) {
    return "Split the next prompt to one subsystem and one measurable success criterion.";
  }
  if (previous.friction.some((item) => /build|deploy|bundle/i.test(item))) {
    return "Separate source-level proof from live-bundle proof, and name which one is still missing.";
  }
  return "Add one sentence after verification that says what the prompt factory should do better next time.";
}
function buildSelfImprovementPrompts(input) {
  const maxPrompts = Math.max(1, Math.min(3, Math.floor(input.maxPrompts ?? 3)));
  const loopUpgrade = chooseLoopUpgrade(input.previous);
  const friction = input.previous.friction.slice(0, 5);
  const blockedOpportunities = input.opportunities.filter((opportunity) => opportunity.blockedBy?.length).map((opportunity) => ({
    id: opportunity.id,
    goal: opportunity.goal,
    blockedBy: opportunity.blockedBy ?? []
  }));
  const basePromptCounts = {
    generated: 0,
    blocked: blockedOpportunities.length,
    totalOpportunities: input.opportunities.length
  };
  if (input.previous.status !== "verified" || input.previous.evidence.length === 0) {
    return {
      prompts: [],
      recommendedPromptId: null,
      recommendedPromptReason: null,
      verificationReportTemplate,
      nextAction: "verify-current-work",
      promptCounts: basePromptCounts,
      stopReason: "Previous work needs fresh pass/fail evidence before new prompts can run.",
      loopReview: {
        action: "verify-current-work",
        reason: "Previous work is not complete with evidence, so new prompts would create prompt spam.",
        loopUpgrade,
        friction,
        blockedOpportunities
      }
    };
  }
  const prompts = input.opportunities.filter((opportunity) => !opportunity.blockedBy?.length).map((opportunity) => ({
    opportunity,
    score: opportunityScore(opportunity)
  })).sort((left, right) => right.score - left.score).slice(0, maxPrompts).map(({ opportunity, score }) => ({
    id: opportunity.id,
    title: opportunity.goal,
    score,
    rollbackRisk: opportunity.rollbackRisk,
    prompt: buildPrompt(opportunity, input.previous, loopUpgrade)
  }));
  return {
    prompts,
    recommendedPromptId: prompts[0]?.id ?? null,
    recommendedPromptReason: prompts[0] ? `Highest score ${prompts[0].score}: ${prompts[0].title}` : null,
    verificationReportTemplate,
    nextAction: prompts.length ? "run-recommended-prompt" : blockedOpportunities.length ? "clear-blockers" : "idle",
    promptCounts: {
      ...basePromptCounts,
      generated: prompts.length
    },
    stopReason: prompts.length ? null : blockedOpportunities.length ? "All remaining opportunities are blocked." : "No unblocked opportunities are ready.",
    loopReview: {
      action: "generate-prompts",
      reason: prompts.length ? `Generated ${prompts.length} evidence-backed prompt${prompts.length === 1 ? "" : "s"}.` : "No unblocked opportunities are ready.",
      loopUpgrade,
      friction,
      blockedOpportunities
    }
  };
}

