var DEFAULT_REGISTRY_URL = "https://raw.githubusercontent.com/zaraa-ai/plugin-registry/main/registry.json";
var PluginRegistry = class {
  registryUrl;
  fetchFn;
  cache = null;
  cacheExpiry = 0;
  constructor(config = {}) {
    this.registryUrl = config.registryUrl || DEFAULT_REGISTRY_URL;
    this.fetchFn = config.fetchFn || globalThis.fetch;
  }
  async search(query) {
    const all = await this.list();
    const lower = query.toLowerCase();
    return all.filter(
      (p) => p.name.toLowerCase().includes(lower) || p.description.toLowerCase().includes(lower)
    );
  }
  async list() {
    if (this.cache && Date.now() < this.cacheExpiry) return this.cache;
    try {
      const res = await this.fetchFn(this.registryUrl);
      if (!res.ok) return [];
      const data = await res.json();
      this.cache = data.plugins || [];
      this.cacheExpiry = Date.now() + 5 * 60 * 1e3;
      return this.cache;
    } catch {
      return [];
    }
  }
};

