var UNDO_PATTERNS = [
  /^undo\b/i,
  /\bundo\s+(that|this|it|the\s+(last|previous))\b/i,
  /^revert\b/i,
  /\brevert\s+(that|this|it|the\s+(last|previous))\b/i,
  /\bput\s+it\s+back\b/i,
  /\broll\s*back\b/i,
  /\brestore\s+(the\s+)?(previous|original|old)\b/i
];
var NOT_UNDO_PATTERNS = [
  /\b(explain|how|what|does|about|works)\b.*\bundo\b/i,
  /\bundo\b.*\b(explain|how|what|does|work)\b/i
];
function detectUndoIntent(message) {
  if (NOT_UNDO_PATTERNS.some((p) => p.test(message))) return false;
  return UNDO_PATTERNS.some((p) => p.test(message));
}

