// src/voice/ram-aware-voice-priority.ts
function recommendVoiceRamPriority(input) {
  const signals = collectSignals(input);
  const pressure = input.ram.memory.pressure.status;
  const latency = input.ttsLatencyStatus ?? "good";
  if (pressure === "red" || latency === "blocked") {
    return {
      level: "critical",
      protectionMode: "hard",
      score: 100,
      schedulerHint: "pause-heavy-work",
      recheckAfterMs: 15e3,
      recommendedActions: ["prefer-voice", "pause-heavy-work", "retry-after-pressure-drops"],
      diagnosticSummary: buildDiagnosticSummary("critical", 100, "pause-heavy-work", signals),
      shouldCopyDiagnostics: true,
      shouldPreferVoice: true,
      shouldDeferHeavyWork: true,
      reason: "RAM or voice path is under critical pressure.",
      recommendation: "Keep voice responsive: pause non-voice local builds, defer model loads, and retry voice after pressure drops.",
      signals
    };
  }
  if (pressure === "yellow" || latency === "degraded") {
    return {
      level: "elevated",
      protectionMode: "soft",
      score: 60,
      schedulerHint: "prefer-voice",
      recheckAfterMs: 6e4,
      recommendedActions: ["prefer-voice", "defer-heavy-work", "copy-diagnostics-if-persistent"],
      diagnosticSummary: buildDiagnosticSummary("elevated", 60, "prefer-voice", signals),
      shouldCopyDiagnostics: true,
      shouldPreferVoice: true,
      shouldDeferHeavyWork: true,
      reason: "RAM or voice latency is degraded enough to protect voice responsiveness.",
      recommendation: "Prefer voice work, avoid starting heavy jobs, and copy diagnostics if latency stays degraded.",
      signals
    };
  }
  return {
    level: "normal",
    protectionMode: "off",
    score: 0,
    schedulerHint: "normal",
    recheckAfterMs: 3e5,
    recommendedActions: ["run-voice-normally"],
    diagnosticSummary: buildDiagnosticSummary("normal", 0, "normal", signals),
    shouldCopyDiagnostics: false,
    shouldPreferVoice: false,
    shouldDeferHeavyWork: false,
    reason: "RAM pressure and voice latency are healthy.",
    recommendation: "Run voice normally.",
    signals
  };
}
function buildDiagnosticSummary(level, score, schedulerHint, signals) {
  return `level=${level} score=${score} scheduler=${schedulerHint} ${signals.join(" ")}`;
}
function collectSignals(input) {
  const memory = input.ram.memory;
  const signals = [
    `ram:${memory.pressure.status}`,
    `tts:${input.ttsLatencyStatus ?? "good"}`,
    `used:${formatGiB(memory.usedBytes)}`
  ];
  if (memory.swapUsedBytes !== null && memory.swapUsedBytes > 0) {
    signals.push(`swap:${formatGiB(memory.swapUsedBytes)}`);
  }
  const heaviestProcess = input.ram.topProcesses[0];
  if (heaviestProcess) {
    signals.push(`top:${heaviestProcess.command}`);
  }
  for (const warning of input.ram.warnings) {
    signals.push(`warning:${warning}`);
  }
  return signals;
}
function formatGiB(bytes) {
  return `${(bytes / 1024 / 1024 / 1024).toFixed(1)}GiB`;
}

