// src/earner/caption-cta.ts
var DISCLAIMER = "Education / entertainment only \u2014 no returns promised; content library, not auto-post.";
function sanitizeCaptionTopic(topic, maxLen = 48) {
  const cleaned = String(topic || "").replace(new RegExp("\\p{Cc}", "gu"), " ").replace(/\s+/g, " ").trim();
  const base = cleaned || "this";
  return base.length > maxLen ? `${base.slice(0, maxLen - 1)}\u2026` : base;
}
function templatesFor(mode, topic) {
  const t = topic;
  if (mode === "education_only") {
    return [
      {
        type: "education",
        text: `Learn the ${t} playbook \u2014 no hype, just the steps.`
      },
      {
        type: "question",
        text: `What part of ${t} are you stuck on right now?`
      },
      {
        type: "education",
        text: `Save this ${t} breakdown for your next session.`
      }
    ];
  }
  if (mode === "soft") {
    return [
      {
        type: "direct",
        text: `Try the free ${t} checklist \u2014 link in bio.`
      },
      {
        type: "question",
        text: `Which ${t} step would you test first \u2014 A or B?`
      },
      {
        type: "education",
        text: `Quiet tip: improve one ${t} habit this week (no FOMO).`
      }
    ];
  }
  return [
    {
      type: "direct",
      text: `Ship your next ${t} draft today \u2014 grab the template.`
    },
    {
      type: "question",
      text: `What's the one ${t} blocker you want cleared this week?`
    },
    {
      type: "urgency",
      text: `This week's ${t} brief closes Friday \u2014 seats are limited.`
    }
  ];
}
function buildCaptionCtaPack(topic, mode = "full") {
  const safeMode = mode === "soft" || mode === "education_only" || mode === "full" ? mode : "full";
  const safeTopic = sanitizeCaptionTopic(topic);
  const variants = templatesFor(safeMode, safeTopic);
  return {
    mode: safeMode,
    topic: safeTopic,
    variants,
    suppressAggressiveMoney: safeMode !== "full",
    disclaimer: DISCLAIMER,
    autoPost: false
  };
}
function captionCtaHasReturnsClaim(pack) {
  const re = /\b(guaranteed|get rich|100%\s*returns?|risk[\s-]?free|double your money)\b/i;
  return pack.variants.some((v) => re.test(v.text));
}

// src/earner/ugc-brief.ts
var DEFAULT_MUST_NOT = [
  "No financial advice",
  "No guaranteed returns",
  "No auto-post / live-ad path"
];
var DISCLAIMER2 = "Education / entertainment only \u2014 no returns promised; creator brief, not auto-post.";
function clean(s, fallback) {
  const t = String(s || "").replace(new RegExp("\\p{Cc}", "gu"), " ").replace(/\s+/g, " ").trim();
  return t || fallback;
}
function buildUgcBrief(input) {
  const campaign = clean(input.campaign, "untitled campaign");
  const platform = input.platform ?? "reels";
  const hook = clean(input.hook, `Open on the problem \u2014 first 3s for ${campaign}`);
  const deliverableLength = clean(input.deliverableLength, "15\u201330s");
  const rights = clean(input.rights, "Organic only");
  const deadline = input.deadline?.trim() ? input.deadline.trim() : null;
  const mustSay = (input.mustSay ?? []).map((s) => clean(s, "")).filter(Boolean);
  const mustNotSay = [
    ...DEFAULT_MUST_NOT,
    ...(input.mustNotSay ?? []).map((s) => clean(s, "")).filter(Boolean)
  ];
  const mode = input.ctaMode ?? "full";
  const topic = clean(input.topic, campaign);
  const cta = buildCaptionCtaPack(topic, mode);
  const brief = {
    campaign,
    platform,
    hook,
    deliverableLength,
    rights,
    deadline,
    mustSay,
    mustNotSay,
    cta,
    disclaimer: DISCLAIMER2,
    autoPost: false,
    doneCheck: {
      hookFilled: Boolean(hook),
      deliverableFilled: Boolean(deliverableLength),
      rightsFilled: Boolean(rights),
      threeCtas: cta.variants.length === 3,
      disclaimerPresent: true
    }
  };
  return brief;
}
function ugcBriefComplete(brief) {
  const d = brief.doneCheck;
  return d.hookFilled && d.deliverableFilled && d.rightsFilled && d.threeCtas && d.disclaimerPresent && brief.autoPost === false;
}
